def make_list(values, tail_to=None):
    """Link the values into a list and return its nodes. The last node's next points back at nodes[tail_to] (no cycle when tail_to is None)."""
    nodes = [ListNode(value) for value in values]
    for before, after in zip(nodes, nodes[1:]):
        before.next = after
    if tail_to is not None:
        nodes[-1].next = nodes[tail_to]
    return nodes
def describe_node(nodes, node):
    if node is None:
        return "None"
    for index, candidate in enumerate(nodes):
        if candidate is node:
            return f"the node at index {index} (value {node.val})"
    return "something that is not a node of this list"
def finds_cycle_start(values, tail_to=None):
    """Call cycle_start on that list: True when it returns the node at index tail_to (None when there is no cycle) and leaves every node as it was."""
    nodes = make_list(values, tail_to)
    before = [(node.val, node.next) for node in nodes]
    got = cycle_start(nodes[0] if nodes else None)
    expected = None if tail_to is None else nodes[tail_to]
    if got is not expected:
        wanted = "None (the list has no cycle)" if expected is None else describe_node(nodes, expected)
        raise AssertionError(f"expected {wanted}, got {describe_node(nodes, got)}")
    if [(node.val, node.next) for node in nodes] != before or any(len(vars(node)) != 2 for node in nodes):
        raise AssertionError("cycle_start changed the list: a val, a next, or a new attribute on a node")
    return True
class WatchedNode(ListNode):
    """A ListNode that counts every ==. A set or a dict never compares nodes that way; looking a node up in a list does."""
    comparisons = 0

    def __eq__(self, other):
        WatchedNode.comparisons += 1
        return self is other

    __hash__ = object.__hash__
def compares_nodes_rarely(length, allowed):
    """A watched list of `length` nodes whose cycle is at the very end (the worst case for a list of visited nodes)."""
    nodes = [WatchedNode(i) for i in range(length)]
    for before, after in zip(nodes, nodes[1:]):
        before.next = after
    nodes[-1].next = nodes[-1]
    WatchedNode.comparisons = 0
    got = cycle_start(nodes[0])
    if got is not nodes[-1]:
        raise AssertionError(f"expected the last node (value {length - 1}), got {describe_node(nodes, got)}")
    if WatchedNode.comparisons > allowed:
        raise AssertionError(f"compared nodes with == {WatchedNode.comparisons} times on {length} nodes (about {allowed} is the most a linear solution needs): looking each node up in a list of visited nodes is O(n²)")
    return True
